theorem squareTrace_nonneg_iff_real {nodes : Finset ℂ}
    (hclosed : ∀ z ∈ nodes, conj z ∈ nodes) {weight : ℂ → ℝ}
    (hweight : ∀ z ∈ nodes, 0 < weight z) :
    (∀ p : Polynomial ℝ, p.degree < (nodes.card : WithBot ℕ) →
      0 ≤ (squareTrace nodes weight p).re) ↔
    ∀ z ∈ nodes, z.im = 0
